def factorial_recursive(n):
    """Ríomhann fachtóiriúl n ag baint úsáide as atriall."""
    if not isinstance(n, int) or n < 0:
        raise ValueError("Ní mór ionchur a bheith ina slánuimhir neamhdhiúltach.")

    # Cás bunúsach
    if n == 0:
        return 1

    # Céim atriallach
    return n * factorial_recursive(n - 1)

# Úsáid shamplach:
# print(factorial_recursive(5))  # Tugann sé 120 ar ais
# print(factorial_recursive(0))  # Tugann sé 1 ar ais

python
def factorial_recursive(n):
    """
    Ríomhann sé fachtóireacht na slánuimhreach neamhdhiúltaí n ag baint úsáide as athchúrsáil.
    Sainmhínítear fachtóireacht 0 mar 1.

    Raises:
        ValueError: Má tá n diúltach.
    """
    if n < 0:
        raise ValueError("Níl fachtóireacht sainmhínithe le haghaidh uimhreacha diúltacha.")
    elif n == 0:
        return 1
    else:
        return n * factorial_recursive(n - 1)

# Sampla úsáide:
