def fibonacci_recursive(n):
    """Ríomhann sé an uimhir Fibonacci nú ag úsáid athchúrsála.
    Filleann sé 0 d'ionchuir neamhdhearfacha.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

